import { isValidToolName } from "../agent-tool/types.js";
import { assertHandleDescriptionNotEmpty } from "../shared/handle-description.js";
function targetOf(opts) {
    return ("app" in opts && opts.app !== undefined ? opts.app : opts.element);
}
function filterVariableToken(variable) {
    return {
        id: variable.id.value,
        name: variable.name,
        description: variable.description,
        required: variable.required,
    };
}
function serializeRunAs(runAs) {
    if ("currentUser" in runAs)
        return { currentUser: true };
    if ("publisher" in runAs)
        return { publisher: true };
    return { serviceAccount: runAs.serviceAccount };
}
function common(opts) {
    // Authoring-layer name check (mirrors entities/agent/tools.ts's common()) —
    // every tool factory routes through here, so this is the single
    // enforcement point; the tf passes never re-check.
    if (!isValidToolName(opts.name)) {
        throw new Error(`skill tool name "${opts.name}" must be 1–64 characters of letters, digits, and ` +
            `underscores (A–Z, a–z, 0–9, _) with no consecutive underscores — no hyphens or spaces.`);
    }
    return {
        name: opts.name,
        description: opts.description,
        status: opts.status ?? "ACTIVE",
        ...(opts.startMessage !== undefined ? { startMessage: opts.startMessage } : {}),
        ...(opts.runAs !== undefined ? { runAs: serializeRunAs(opts.runAs) } : {}),
    };
}
function tool(value) {
    return value;
}
function searchFieldToken(f) {
    if ("fieldId" in f) {
        // Raw platform id fallback — see SkillSearchRawIdField's comment.
        return {
            fieldId: f.fieldId.value,
            name: f.name,
            description: f.description,
        };
    }
    return {
        fieldId: f.field,
        clientHandle: f.field,
        name: f.name,
        description: f.description,
    };
}
function recordFieldToken(f) {
    if ("fieldId" in f) {
        // Raw platform id fallback — see SkillRecordRawIdField's comment.
        return {
            fieldId: f.fieldId.value,
            name: f.name,
            description: f.description,
            required: f.required,
            ...(f.defaultValue !== undefined ? { defaultValue: f.defaultValue } : {}),
        };
    }
    return {
        fieldId: f.field,
        clientHandle: f.field,
        name: f.name,
        description: f.description,
        required: f.required,
        ...(f.defaultValue !== undefined ? { defaultValue: f.defaultValue } : {}),
    };
}
export function skillAutomation(opts) {
    const inputEntries = Object.entries((opts.inputs ?? {}));
    const inputs = inputEntries.map(([parameterName, spec]) => ({
        parameterName,
        displayName: spec.name ?? parameterName,
        description: spec.description,
        ...(spec.required !== undefined ? { required: spec.required } : {}),
    }));
    const outputEntries = Object.entries((opts.outputs ?? {}));
    const outputs = outputEntries.map(([workflowPropertyName, spec]) => ({
        workflowPropertyName,
        displayName: spec?.name ?? workflowPropertyName,
    }));
    return tool({
        automation: {
            ...common(opts),
            automationId: opts.automation,
            ...(inputs.length > 0 ? { inputs } : {}),
            ...(outputs.length > 0 ? { outputs } : {}),
        },
    });
}
export function skillSearchRecords(opts) {
    return tool({
        searchAspect: {
            ...common(opts),
            aspectId: targetOf(opts),
            queryDescription: opts.queryDescription,
            ...(opts.fields !== undefined ? { fields: opts.fields.map(searchFieldToken) } : {}),
            ...(opts.limit !== undefined ? { limit: opts.limit } : {}),
            ...(opts.filterVariables !== undefined ? { filterVariables: opts.filterVariables.map(filterVariableToken) } : {}),
        },
    });
}
export function skillSearchTable(opts) {
    return tool({
        searchTable: {
            ...common(opts),
            aspectId: targetOf(opts),
            searchTableId: opts.table,
            queryDescription: opts.queryDescription,
            fields: opts.fields.map(searchFieldToken),
            ...(opts.limit !== undefined ? { limit: opts.limit } : {}),
            ...(opts.filterVariables !== undefined ? { filterVariables: opts.filterVariables.map(filterVariableToken) } : {}),
        },
    });
}
export function skillCreateRecord(opts) {
    return tool({
        createRecord: {
            ...common(opts),
            aspectId: targetOf(opts),
            fields: (opts.fields ?? []).map(recordFieldToken),
        },
    });
}
export function skillUpdateRecord(opts) {
    assertHandleDescriptionNotEmpty(opts.handleDescription, "skillUpdateRecord");
    return tool({
        updateRecord: {
            ...common(opts),
            aspectId: targetOf(opts),
            fields: (opts.fields ?? []).map(recordFieldToken),
            ...(opts.handleDescription !== undefined ? { handleDescription: opts.handleDescription } : {}),
        },
    });
}
export function skillRunAgent(opts) {
    return tool({
        runAgent: {
            ...common(opts),
            targetAgentId: opts.agent,
            workerTaskPrompt: opts.workerTaskPrompt,
        },
    });
}
